2158	\begin{theorem}[Separate components in the isometry transfer]
2159	\label{thm:pauli-component-isometry-transfer-support}
2160	\lean{MIPStarRE.QPBT.ExtractionWitness.pauli_distance_alice_le_components}
2161	\lean{MIPStarRE.QPBT.ExtractionWitness.pauli_distance_bob_le_components}
