from pathlib import Path
import re,subprocess
patch=Path('/home/drx/.cache/mipstarre-dev/reviews/pr736/b9cf07572bc08c48b81947054a11f23e6e577ac5/diff.patch').read_text()
base='dfb1084d7e6aacb1323b5b9f192e65d4eb1cf787'
pat=re.compile(r'"'^(?:noncomputable )?(?:theorem|lemma|def|structure|abbrev)'"\\s+(\\S+)[\\s\\S]*?(?=:= by|:=|\\n\\n)',re.M)
for b in patch.split('diff --git ')[1:]:
 f=b.split(' b/')[1].splitlines()[0]
 if not f.startswith('MIPStarRE/') or not f.endswith('.lean'): continue
 old=subprocess.run(['git','show',base+':'+f],capture_output=True,text=True)
 if old.returncode: continue
 before={m[1]:re.sub(r'\\s+',' ',m[0]) for m in pat.finditer(old.stdout)}
 after={m[1]:re.sub(r'\\s+',' ',m[0]) for m in pat.finditer(Path(f).read_text())}
 for name in before.keys()&after.keys():
  if before[name]"'!=after[name]: print(f,name,'"'\\nOLD',before[name],'\\nNEW',after[name])
PY"

